    35→/**
    36→ * This is principal class that perform the dependency analysis in a Gradle project.
    37→ */
    38→@Slf4j
    39→@Component(role = GradleProjectDependencyAnalyzer.class)
    40→public class DefaultGradleProjectDependencyAnalyzer
    41→        implements GradleProjectDependencyAnalyzer {
    42→
    43→  @Requirement
    44→  private final ClassAnalyzer classAnalyzer = new DefaultClassAnalyzer();
    45→
    46→  @Requirement
    47→  private final DependencyAnalyzer dependencyAnalyzer = new ASMDependencyAnalyzer();
    48→
    49→  /**
    50→   * If true, the project's classes in target/test-classes are not going to be analyzed.
    51→   */
    52→  private final boolean isIgnoredTest;
    53→
    54→  /**
    55→   * A map [artifact] -> [allTypes].
    56→   */
    57→  private Map<ResolvedArtifact, Set<String>> artifactClassesMap;
    58→
    59→  /**
    60→   * A map [artifact] -> [usedTypes].
    61→   */
    62→  private final Map<ResolvedArtifact, Set<String>> artifactUsedClassesMap = new HashMap<>();
    63→
    64→  /**
    65→   * Ctor.
    66→   */
    67→  public DefaultGradleProjectDependencyAnalyzer(final boolean isIgnoredTest) {
    68→    this.isIgnoredTest = isIgnoredTest;
    69→  }
    70→
    71→  /**
    72→   * Analyze the dependencies in a project.
    73→   *
    74→   * @param project The Gradle project to be analyzed.
    75→   * @return An object with the usedDeclaredArtifacts, usedUndeclaredArtifacts,
    76→   *        and unusedDeclaredArtifacts.
    77→   * @see <code>ProjectDependencyAnalyzer#analyze(org.apache.invoke.project.MavenProject)</code>
    78→   */
    79→  @SneakyThrows
    80→  @Override
    81→  public GradleProjectDependencyAnalysis analyze(final Project project) {
    82→      // project's configurations.
    83→      ConfigurationContainer configurationContainer = project.getConfigurations();
    84→      Set<Configuration> configurations = new HashSet<>(configurationContainer);
    85→
    86→      DependencyUtils utils = new DependencyUtils();
    87→      // all resolved dependencies including transitive ones of the project.
    88→      Set<ResolvedDependency> allDependencies = utils.getAllDependencies(configurations);
    89→
    90→      // all resolved artifacts of this project
    91→      Set<ResolvedArtifact> allArtifacts = new HashSet<>();
    92→      for (ResolvedDependency dependency : allDependencies) {
    93→        allArtifacts.addAll(dependency.getModuleArtifacts());
    94→      }
    95→
    96→      // a map of [dependency] -> [classes]
    97→      artifactClassesMap = buildArtifactClassMap(allArtifacts);
    98→
    99→      // direct dependencies of the project
   100→      Set<ResolvedDependency> declaredDependencies = utils.getDeclaredDependencies(configurations);
   101→
   102→      // direct artifacts of the project
   103→      Set<ResolvedArtifact> declaredArtifacts = utils.getDeclaredArtifacts(declaredDependencies);
   104→
   105→      /* ******************** bytecode analysis ********************* */
   106→
   107→      // execute the analysis (note that the order of these operations matters!)
   108→      buildProjectDependencyClasses(project);
   109→      Set<String> projectClasses = new HashSet<>(DefaultCallGraph.getProjectVertices());
   110→      buildDependenciesDependencyClasses(project);
   111→
   112→      /* ******************** usage analysis ********************* */
   113→
   114→      // search for the dependencies used by the project
   115→      Set<ResolvedArtifact> usedArtifacts = collectUsedArtifacts(
   116→              artifactClassesMap,
   117→              DefaultCallGraph.referencedClassMembers(projectClasses)
   118→      );
   119→
   120→      /* ******************** results as statically used at the bytecode *********************** */
   121→
   122→      // for the used dependencies, get the ones that are declared
   123→      Set<ResolvedArtifact> usedDeclaredArtifacts = new LinkedHashSet<>(declaredArtifacts);
   124→      usedDeclaredArtifacts.retainAll(usedArtifacts);
   125→
   126→      // for the used dependencies, remove the ones that are declared
   127→      Set<ResolvedArtifact> usedUndeclaredArtifacts = new LinkedHashSet<>(usedArtifacts);
   128→      usedUndeclaredArtifacts = removeAll(usedUndeclaredArtifacts, declaredArtifacts);
   129→
   130→      // for the declared dependencies, get the ones that are not used
   131→      Set<ResolvedArtifact> unusedDeclaredArtifacts = new LinkedHashSet<>(declaredArtifacts);
   132→      unusedDeclaredArtifacts = removeAll(unusedDeclaredArtifacts, usedArtifacts);
   133→
   134→      return new GradleProjectDependencyAnalysis(usedDeclaredArtifacts,
   135→              usedUndeclaredArtifacts, unusedDeclaredArtifacts);
   136→
   137→  }
