   139→  /**
   140→   * Returns a map with the artifacts (dependencies) in a Gradle project and
   141→   * their corresponding classes.
   142→   *
   143→   * @param allArtifacts File of each artifact.
   144→   * @return A map of artifact -> classes.
   145→   * @throws IOException If the class cannot be analyzed.
   146→   */
   147→  public Map<ResolvedArtifact, Set<String>> buildArtifactClassMap(
   148→          final Set<ResolvedArtifact> allArtifacts) throws IOException {
   149→    Map<ResolvedArtifact, Set<String>> artifactClassMap = new LinkedHashMap<>();
   150→    for (ResolvedArtifact artifact : allArtifacts) {
   151→      File file = artifact.getFile();
   152→      if (file.getName().endsWith(".jar")) {
   153→        // optimized solution for the jar case
   154→        try (JarFile jarFile = new JarFile(file)) {
   155→          Enumeration<JarEntry> jarEntries = jarFile.entries();
   156→          Set<String> classes = new HashSet<>();
   157→          while (jarEntries.hasMoreElements()) {
   158→            String entry = jarEntries.nextElement().getName();
   159→            if (entry.endsWith(".class")) {
   160→              String className = entry.replace('/', '.');
   161→              className = className.substring(0, className.length() - ".class".length());
   162→              classes.add(className);
   163→            }
   164→          }
   165→          artifactClassMap.put(artifact, classes);
   166→        }
   167→      } else if (file.isDirectory()) {
   168→        URL url = file.toURI().toURL();
   169→        Set<String> classes = classAnalyzer.analyze(url);
   170→        artifactClassMap.put(artifact, classes);
   171→      }
